import argparse,hashlib,json,os,shutil,subprocess,tempfile,time
from pathlib import Path
from datetime import datetime,timezone

def run(cmd,**kwargs):return subprocess.run(cmd,check=True,**kwargs)
def digest(b):return hashlib.sha256(b).hexdigest()
def check_files(root):
 pending=[]
 for rel,expected,content in FILES:
  p=root/rel
  if p.is_symlink():raise SystemExit('SYMLINK_NOT_SUPPORTED: '+rel)
  current=p.read_bytes() if p.is_file() else None
  wanted=content.encode('utf8')
  if current==wanted:continue
  if (current is None and expected is not None) or (current is not None and digest(current)!=expected):
   raise SystemExit('VERSION_MISMATCH: '+rel+'; no files changed. Send this line; do not bypass.')
  compile(content,rel,'exec')
  pending.append((rel,content,current))
 return pending

def atomic(path,data):
 path.parent.mkdir(parents=True,exist_ok=True)
 fd,tmp=tempfile.mkstemp(dir=path.parent,prefix=path.name+'.')
 try:
  with os.fdopen(fd,'wb') as f:f.write(data)
  if path.exists():shutil.copymode(path,tmp)
  os.replace(tmp,path)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)

def main():
 parser=argparse.ArgumentParser(description='Install verified public developer adapters and repair discovery reporting. Existing OCR/LLM, no duplicate models.')
 parser.add_argument('--check-only',action='store_true',help='check source versions without Docker or writes')
 parser.add_argument('--diagnose-only',action='store_true',help='read GPB gate and saved handoff failures; no HTTP, tasks or DB writes')
 args=parser.parse_args();root=Path.cwd()
 if not (root/'app/workers/celery_app.py').is_file():raise SystemExit('Run from ~/LLM-assistant/tender-ai-platform-v6.2')
 if args.diagnose_only:
  run(['docker','compose','exec','-T','app','python','-'],input=DIAG,text=True,timeout=90);return
 pending=check_files(root)
 print('SOURCE_GUARDS_OK; CHANGES:',len(pending),flush=True)
 if args.check_only:return
 # Never replace the already installed dashboard policy with an older image's files.
 ui=(root/'app/static/index.html').read_text()
 gate=(root/'app/reports/dashboard_eligibility.py').read_text()
 if 'allTenders = main.tenders;' not in ui or "'manual_review', 'needs_clarification'" not in gate:
  raise SystemExit('DASHBOARD_POLICY_NOT_CURRENT: no changes; update repository checkout from installed app before rebuilding')
 # Diagnose current card without reviving manually dismissed records.
 diag=run(['docker','compose','exec','-T','app','python','-'],input=DIAG,text=True,timeout=90)
 backup=root/'backups'/('sources-connect-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
 try:
  for rel,content,current in pending:
   if current is not None:atomic(backup/rel,current)
  if pending:
   atomic(backup/'manifest.json',json.dumps({'files':[{'path':rel,'new_file':old is None} for rel,_,old in pending]},indent=2).encode())
   for rel,content,current in pending:atomic(root/rel,content.encode('utf8'))
   print('BACKUP:',backup,flush=True)
  run(['docker','compose','build','app','celery_worker','celery_discovery','celery_beat'])
  run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,timeout=120)
 except BaseException:
  for rel,_,old in pending:
   if old is None:(root/rel).unlink(missing_ok=True)
   else:atomic(root/rel,old)
  print('BUILD_OR_TEST_FAILED: source restored; running services were not restarted',flush=True)
  raise
 # Ask workers to finish their current tasks; never use SIGKILL/queue purge.
 running=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True).stdout.split()
 services=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in running]
 ids=[]
 for s in services:ids.extend(run(['docker','compose','ps','-q',s],capture_output=True,text=True).stdout.split())
 if services:
  print('Waiting for worker warm shutdown; existing tasks may finish.',flush=True)
  run(['docker','compose','kill','--signal','SIGTERM',*services])
  until=time.monotonic()+300
  while ids:
   states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True).stdout.split()
   if all(s=='false' for s in states):break
   if time.monotonic()>until:
    raise SystemExit('WARM_SHUTDOWN_PENDING: no forced stop. Let active tasks finish, then rerun this same installer.')
   time.sleep(3)
 run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery','celery_beat'])
 print('SOURCES_CONNECT_INSTALLED: glavstroy, samolet; shared OCR/LLM; max two cards/source/run',flush=True)
 print('ETPRF_SCHEDULE_DISABLED; METAL_HANDOFF_FAILURE_REPORTING_FIXED; TIFF_MULTIPAGE_INSTALLED',flush=True)
 run(['docker','compose','exec','-T','celery_discovery','python','-'],input=VERIFY,text=True,timeout=60)
 print('No immediate collection, mass requeue, DB edits or notifications. Existing schedules retained except etprf; new source schedules added.',flush=True)

if __name__=='__main__':main()
